      task_label: task_info[obj.task_code],
      team: obj.team ? obj.team.replaceAll("_", "-") : obj.site.replaceAll("_", "-"),
      dataset: obj.dataset.replaceAll("_", "-"),
      date: parse_time(obj.time_started),
    })
  })
    .filter(d =&gt; d.task_label !== "NA")
    .sort((a, b) =&gt; {
