// get scores table for a given dataset
async function getScores(dataset) {
  console.log('getting scores')
  const rows = await redivis
    .organization('LEVANTE')
    .dataset(dataset)
    .table('scores')
    .listRows()
  console.log('got scores')
  return rows;
}

// get references to all LEVANTE datasets (with "properties" populated)
async function getDatasets() {
  const ds = await redivis
    .organization('LEVANTE')
    .listDatasets()
  return await Promise.all(ds.map(d =&gt; d.get()))
}

// filter datasets by authed user's access + get names of "processed" datasets
allowedDatasetNames = (ds) =&gt; {
  const accessLevels = ["data", "edit"]
  //const extraDatasets = ["levante-data-latest", "levante-data-pilots-hackathon"]
  const defaultDataset = "levante-data-pilots"
  const datasets = ds.filter(d =&gt; accessLevels.includes(d.properties.accessLevel))
    .filter(d =&gt; d.properties.tableCount &gt; 0)
    .map(d =&gt; d.name)
    .filter(n =&gt; !n.match("-raw|-metadata-|-example"))
    //.filter(n =&gt; n.match("processed") || extraDatasets.includes(n))
    .sort()
  return [defaultDataset, ...datasets]
}

